import { render } from "@testing-library/react";
import { MemoryRouter } from "react-router-dom";
import { vi } from "vitest";

import App from "../App";
import type { AssessmentRecord, HealthView, PreparednessReport } from "../api/types";
import completeJson from "./fixtures/report-complete.json";
import demoJson from "./fixtures/report-demo-complete.json";
import incompleteJson from "./fixtures/report-incomplete.json";
import needsReviewJson from "./fixtures/report-needs-review.json";

// Fixtures are generated by `python -m backend.tests.export_fixtures frontend/src/test/fixtures`.
const clone = <T,>(v: unknown): T => structuredClone(v) as T;
export const fixtures = {
  complete: () => clone<PreparednessReport>(completeJson),
  needsReview: () => clone<PreparednessReport>(needsReviewJson),
  incomplete: () => clone<PreparednessReport>(incompleteJson),
  demo: () => clone<PreparednessReport>(demoJson),
};

export function recordFor(report: PreparednessReport): AssessmentRecord {
  return {
    report_id: report.report_id,
    created_at: report.created_at,
    duration_ms: 120.5,
    request: {
      place: { name: report.query, district: null, state: null },
      forecast_days: 3,
      profile: {
        elderly: true,
        young_children: false,
        pregnant_women: false,
        chronic_illness_group: false,
        outdoor_workers: true,
        farmers: true,
        limited_water_access: false,
        limited_shade_or_cooling: false,
        terrain: "plains",
        preferred_language: "en",
      },
    },
    report,
  };
}

export const LIVE_HEALTH: HealthView = {
  status: "ok",
  version: "0.1.0",
  weather_provider: "open_meteo",
  agent_mode: "bedrock",
  model_id: "test-model",
};

type Reply = { status?: number; body: unknown } | ((init: RequestInit | undefined) => { status?: number; body: unknown });

/**
 * Stubs fetch. Keys are "METHOD /path" (query string ignored) or "METHOD /path?query" for an exact match.
 * GET /api/health answers LIVE_HEALTH unless given.
 */
export function mockApi(routes: Record<string, Reply>) {
  const all: Record<string, Reply> = { "GET /api/health": { body: LIVE_HEALTH }, ...routes };
  return vi.spyOn(globalThis, "fetch").mockImplementation(async (input, init) => {
    const url = new URL(typeof input === "string" ? input : input instanceof URL ? input.href : input.url);
    const method = init?.method ?? "GET";
    const reply = all[`${method} ${url.pathname}${url.search}`] ?? all[`${method} ${url.pathname}`];
    if (!reply) {
      return new Response(JSON.stringify({ error: { code: "not_found", message: "Not found.", fields: [] } }), {
        status: 404,
        headers: { "Content-Type": "application/json" },
      });
    }
    const { status = 200, body } = typeof reply === "function" ? reply(init) : reply;
    return new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json" } });
  });
}

export function renderApp(path: string) {
  return render(
    <MemoryRouter initialEntries={[path]}>
      <App />
    </MemoryRouter>,
  );
}
